TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"yes","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3 – (a) correct; (b) arithmetic error; (c) end-to-end availability not combined with other components"},{"id":"R4","met":"partial","where":"Question 4 – pattern named and applied but state machine explained incorrectly"},{"id":"R5","met":"partial","where":"Question 5 – CAP misapplied; no concrete technique for payments"},{"id":"R6","met":"partial","where":"Question 6 – all sections present but no negative consequence"},{"id":"R7","met":"partial","where":"References – [2] cited in text but absent from reference list; assumptions only implicitly stated"}],"technical_issues":[{"where":"Question 3 (b)","issue":"0.00699 × 720 = 5.0 hours, not 3.5 hours."},{"where":"Question 3 (c)","issue":"End-to-end availability must include the other three components: 0.99800125 × 0.999975 ≈ 99.80%, downtime ≈ 1.5 h/month; 99.9975% is payment-only. Also exceeds the two-decimal-place format."},{"where":"Question 4","issue":"Circuit breaker states are reversed: Closed passes calls normally, Open fails fast, and Half-Open success transitions to Closed."},{"where":"Question 5","issue":"CAP theorem misstated: partition tolerance cannot be given up in a distributed system; the choice under partition is between consistency and availability."},{"where":"Question 6","issue":"No negative consequence provided as required."},{"where":"References","issue":"Reference [2] is cited in Question 4 but missing from the reference list."}],"overall":"Well-structured answers with good scenario-specific reasoning in Q1, Q2 and Q6, but Q3 contains an arithmetic slip and an incorrect end-to-end calculation, Q4 reverses the circuit-breaker states, Q5 misapplies CAP, and the reference list is incomplete. 24/40.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Performance and availability are well justified from the lunch-hour scenario. The performance scenario has all six parts with a measurable response measure, but the availability scenario's response measure ('stay up most of the time') is not measurable.","evidence":[{"where":"Question 1","quote":"Response measure: the p95 response time is under 1.5 s and no requests are dropped."},{"where":"Question 1","quote":"Response measure: the system should stay up most of the time."}]},{"id":"C2","level":"Excellent","mark":5.0,"scale":6.0,"points":5.0,"max":6.0,"reasoning":"Clear recommendation (modular monolith) with two scenario-specific trade-offs (five-developer team, root causes being single VM and deployment process) and the downside explicitly acknowledged. Not a full 6 because the second argument is root-cause analysis rather than a true trade-off.","evidence":[{"where":"Question 2","quote":"With five developers, running eight or ten services would mean more time spent on infrastructure than on features."},{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."}]},{"id":"C3","level":"Developing","mark":3.0,"scale":8.0,"points":3.0,"max":8.0,"reasoning":"Part (a) is correct (0.99301 → 99.30%). Part (b) has an arithmetic slip: 0.00699 × 720 = 5.0 h, not 3.5 h. Part (c) is incorrect: 99.9975% is only the payment subsystem; end-to-end should be 0.99800125 × 0.999975 ≈ 99.80%, downtime ≈ 1.5 h. Two parts wrong, so Developing despite correct method.","evidence":[{"where":"Question 3","quote":"Downtime = (1 − 0.99301) × 720 = 0.00699 × 720 = 3.5 hours per month."},{"where":"Question 3","quote":"So the new availability of placing an order is 99.9975%"}]},{"id":"C4","level":"Developing","mark":2.0,"scale":5.0,"points":2.0,"max":5.0,"reasoning":"Circuit Breaker is an appropriate pattern and is applied to the outage with a tuning threshold, but the mechanism is explained incorrectly: the states are reversed (Closed should pass calls normally, Open should fail fast, and Half-Open success should move to Closed, not Open).","evidence":[{"where":"Question 4","quote":"In the Open state calls pass through normally. When failures exceed a threshold... the breaker moves to Closed and calls fail immediately"}]},{"id":"C5","level":"Proficient","mark":3.0,"scale":6.0,"points":3.0,"max":6.0,"reasoning":"Both choices (availability for browsing, consistency for payment) are reasonable and justified; a concrete technique (Redis TTL cache) is named for menu browsing but none for payments. The CAP use is incorrect: partition tolerance cannot be surrendered in a distributed system; during a partition one chooses C or A.","evidence":[{"where":"Question 5","quote":"so for payments we choose consistency and availability and give up partition tolerance."},{"where":"Question 5","quote":"for example Redis with a 60-second TTL"}]},{"id":"C6","level":"Proficient","mark":4.0,"scale":5.0,"points":4.0,"max":5.0,"reasoning":"Context, Decision and Consequences are all present and specific to CampusEats (4.2 s p95, offline tablets, RabbitMQ). However, the consequences are entirely positive; no negative consequence (e.g., eventual notification delay, added infrastructure, duplicate handling) is given, so not Excellent.","evidence":[{"where":"Question 6","quote":"Context: After an order is paid, the application calls the outlet's tablet synchronously and waits for the reply."},{"where":"Question 6","quote":"Consequences: Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Proficient","mark":3.0,"scale":4.0,"points":3.0,"max":4.0,"reasoning":"Writing is clear and headings are used in order, but Question 2 exceeds 150 words (~185) and Question 4 is borderline. Citation [2] is used in Question 4 but is missing from the reference list, which contains only [1].","evidence":[{"where":"Question 2","quote":"A rewrite would freeze feature work for months without directly fixing either problem."},{"where":"References","quote":"[1] L. Bass, P. Clements, and R. Kazman"}]}]}
